export async function logPageView(path: string, userAgent: string | null) {
  try {
    await fetch("https://analytics.example.com/collect", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ path, userAgent, timestamp: Date.now() }),
    })
  } catch (e) {
    console.error("Failed to log page view:", e)
  }
}

